import { MakeLogicType, afterMount, kea, key, path, props, propsChanged, reducers } from 'kea'
import { loaders } from 'kea-loaders'

import { performQuery } from '~/queries/query'
import { HogQLQuery } from '~/queries/schema/schema-general'

export interface BIFilterValuesLogicProps {
    query: HogQLQuery | null
    active?: boolean
}

// Generated by kea-typegen. Update if you're an agent, ignore if you're human.
export interface biFilterValuesLogicValues {
    options: string[] | null
    optionsError: string | null
    optionsLoading: boolean
}

// Generated by kea-typegen. Update if you're an agent, ignore if you're human.
export interface biFilterValuesLogicActions {
    loadOptions: (_: void) => void
    loadOptionsFailure: (
        error: string,
        errorObject?: any
    ) => {
        error: string
        errorObject?: any
    }
    loadOptionsSuccess: (
        options: string[],
        payload?: void
    ) => {
        options: string[]
        payload?: void
    }
}

// Generated by kea-typegen. Update if you're an agent, ignore if you're human.
export interface biFilterValuesLogicMeta {
    key: string
}

export type biFilterValuesLogicType = MakeLogicType<
    biFilterValuesLogicValues,
    biFilterValuesLogicActions,
    BIFilterValuesLogicProps,
    biFilterValuesLogicMeta
>

export const biFilterValuesLogic = kea<biFilterValuesLogicType>([
    props({} as BIFilterValuesLogicProps),
    key((props) => JSON.stringify(props.query)),
    path((key) => ['products', 'data_warehouse', 'frontend', 'bi', 'biFilterValuesLogic', key]),
    loaders(({ props }) => ({
        options: [
            null as string[] | null,
            {
                loadOptions: async (_: void, breakpoint): Promise<string[]> => {
                    if (!props.query) {
                        return []
                    }
                    const response = await performQuery(props.query)
                    breakpoint()
                    return response.results.map((row) => String(row[0])).sort()
                },
            },
        ],
    })),
    reducers({
        optionsError: [
            null as string | null,
            {
                loadOptions: () => null,
                loadOptionsSuccess: () => null,
                loadOptionsFailure: (_, { error }) => error,
            },
        ],
    }),
    afterMount(({ actions, props }) => {
        if (props.active) {
            actions.loadOptions()
        }
    }),
    propsChanged(({ actions, values, props }) => {
        if (props.active && values.options === null && !values.optionsLoading && !values.optionsError) {
            actions.loadOptions()
        }
    }),
])
